<?php
require_once 'config.php';if($_SESSION['role']!=='Admin'){flash("Only administrators can manage user accounts.","danger");header("Location: dashboard.php");exit;}
$error="";if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf())$error="Invalid form submission. Please try again.";else{$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$role=$_POST['role']??'Officer';if($name===''||$username===''||strlen($pass)<8)$error="Enter a name, username and password of at least 8 characters.";else{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(full_name,username,email,password,role) VALUES(:n,:u,:e,:p,:r)");if($s->execute([':n'=>$name,':u'=>$username,':e'=>$email,':p'=>$hash,':r'=>$role])){$newId=(int)$conn->lastInsertId();audit_log('CREATE','users',$newId,null,['username'=>$username,'role'=>$role]);flash("User account created.");header("Location: users.php");exit;}else$error="Could not create user. The username may already exist.";}}}
$rows=$conn->query("SELECT id,full_name,username,email,role,created_at FROM users ORDER BY id DESC")->fetchAll(PDO::FETCH_ASSOC);$page_title="User Accounts";include 'header.php';?>
<div class="page-heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>User accounts</h1><p class="muted">Create staff accounts for the demonstration system.</p></div></div><section class="panel"><h2>Add a staff account</h2><?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><form method="post" class="form-grid"><?php csrf_field(); ?><div><label>Full name</label><input name="full_name" required></div><div><label>Username</label><input name="username" required></div><div><label>Email</label><input type="email" name="email"></div><div><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required></div><div><label>Role</label><select name="role"><option>Officer</option><option>Admin</option></select></div><div class="span-2"><button class="btn">Create account</button></div></form><hr><h2>Existing users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($r['email'])?></td><td><?=e($r['role'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php include 'footer.php';?>
